-- 0013: Seed proyek contoh "Villa Modern Santika" (rumah modern 2 lantai +
-- rooftop, fasad dua-tona, atap datar berlis fascia, balkon railing kaca, kolam,
-- taman) di akun owner Rumah Qyfa (usr-MPbZPdo6Bj). Layout digenerate & divalidasi
-- oleh generator app (generateLayout) + interior (generateInteriorPlan).
-- Idempotent (on conflict do nothing) + guard owner ada (skip di dev DB tanpa profil).

insert into projects
  (id, owner_id, name, status, readiness, project_type, location, city, province,
   style, thumbnail, floors, rooftop, site, current_version_id, created_at, updated_at)
select $j$proj-modern-lux1$j$, $j$usr-MPbZPdo6Bj$j$, $j$Villa Modern Santika$j$,
  $j$editing$j$, $j$contractor_discussion_ready$j$, $j$new$j$,
  $j$Sidoarjo, Jawa Timur$j$, $j$Sidoarjo$j$, $j$Jawa Timur$j$,
  $j$modern_tropis$j$, $j$vertical$j$, 2, true, $j${"widthM":16,"depthM":20,"areaM2":320,"city":"Sidoarjo","province":"Jawa Timur","frontOrientation":"south","sidesAttached":0,"frontRoadWidthM":8,"notes":"Kavling sudut, hook, jalan lebar 8 m."}$j$::jsonb,
  $j$ver-modern-lux1$j$, now(), now()
where exists (select 1 from profiles where id = $j$usr-MPbZPdo6Bj$j$)
on conflict (id) do nothing;

